const genreTags = {
  romance: ["轻甜爱情", "温暖日常"],
  healing: ["治愈", "日常陪伴"],
  animal: ["动物故事", "陪伴"],
  fantasy: ["轻奇幻", "温柔想象"],
  comedy: ["轻喜剧", "日常温度"],
};

function hash(input) {
  let value = 0;
  for (const ch of String(input)) value = (value * 131 + ch.charCodeAt(0)) >>> 0;
  return value;
}

function pick(list, seed) {
  return list[hash(seed) % list.length];
}

function addDays(base, offset) {
  const date = new Date(base.getTime());
  date.setUTCDate(date.getUTCDate() + offset);
  return date;
}

function formatDate(date) {
  const year = date.getUTCFullYear();
  const month = String(date.getUTCMonth() + 1).padStart(2, "0");
  const day = String(date.getUTCDate()).padStart(2, "0");
  return `${year}-${month}-${day}`;
}

function buildTags(spec) {
  const [, , setting, , , , , object, time, type] = spec;
  const extras = [];
  if (setting.includes("海") || setting.includes("渡") || setting.includes("码头")) extras.push("海风场景");
  else if (setting.includes("山") || setting.includes("林")) extras.push("山间日常");
  else if (setting.includes("邮") || setting.includes("站")) extras.push("往来心意");
  else if (setting.includes("店") || setting.includes("馆") || setting.includes("工作室")) extras.push("小店故事");
  else extras.push("城市微光");
  if (time.includes("秋") || time.includes("白露") || time.includes("寒露")) extras.push("秋日");
  else if (time.includes("冬") || time.includes("雪")) extras.push("冬夜");
  else if (time.includes("春")) extras.push("春天");
  else extras.push("夏日");
  extras.push(object.length <= 6 ? object : object.slice(0, 4));
  return [...genreTags[type], ...extras].slice(0, 4);
}

function descriptionOf(spec) {
  const [, title, setting, role, hero, other, otherRole, object, , type] = spec;
  const direction = type === "animal"
    ? `${hero}在${setting}照看与${object}有关的小生命，也重新安放了自己的心事。`
    : type === "fantasy"
      ? `${hero}在${setting}遇见与${object}相关的温柔奇迹，让普通日子慢慢亮起来。`
      : `${hero}在${setting}守着${object}，和${other}${otherRole ? `这位${otherRole}` : ""}把平常时光过成了柔软的故事。`;
  return direction;
}

function intro(spec) {
  const [, , setting, role, hero, , , object, time, type] = spec;
  const tails = {
    romance: `总会先替人把${object}上的一点光收好。`,
    healing: `会让人觉得连脚步都该放轻一点。`,
    animal: `总先被${object}碰出一声很轻的响。`,
    fantasy: `像是专门留给秘密和奇迹停靠的地方。`,
    comedy: `连空气里都飘着一点手忙脚乱却不惹人烦的甜味。`,
  };
  return `${time}一到，${setting}${tails[type]} ${hero}在这里做${role}，比起把日子过得响亮，她更擅长把每个细小瞬间安安稳稳地接住。`;
}

